from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class Ipaddressv4ParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_localIpAddr()
        self.set_parameter('localIpPrefixLength', self.enb_ent_config['enb_ip_prefix_length'])

    def set_localIpAddr(self):
        if 'enb_ip' in self.enb_ent_config and self.enb_ent_config['enb_ip'] != 'default':
            loc_addr = self.enb_ent_config['enb_ip']
        elif int(self.enb_ent_config['id']) <= 100:
            loc_addr = '10.0.1.' + str(2 * (int(self.enb_ent_config['id'])))
        else:
            loc_addr = '10.0.1.' + str(self.enb_ent_config['id'])

        self.set_parameter('localIpAddr', loc_addr)
